      "index": 5,
      "slo_id": "S5",
      "level": "understand",
      "question": "Which fraction is smaller: $\\frac{1}{2}$ or $\\frac{1}{4}$?",
      "options": [
        "$\\frac{1}{4}$",
        "$\\frac{1}{2}$",
        "They are the same"
      ],
      "correct_index": 0,
      "explanation": "When the numerators are the same, the fraction with the larger denominator is smaller because the whole is divided into more parts.",
      "selected_because": "comparing one over two and one over four using a roti example",
      "distractor_misconceptions": {
        "1": "believes a larger denominator means a larger fraction",
        "2": "thinks fractions with different denominators are always equal"
      },
      "option_feedback": {
        "correct": "That's right! When you divide a roti into 4 pieces, each piece is smaller than if you divide it into 2 pieces.",
        "wrong": {
          "1": "You might be thinking that a larger number in the denominator means a larger fraction. Remember the roti example: if you cut a roti into 4 pieces, each piece is smaller than if you cut it into 2 pieces.",
          "2": "Fractions with different denominators are usually not the same. Think about sharing a roti: one half is much bigger than one quarter."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Comparing one over two and one over four using a roti example.",
      "teaching_error": null
    },
    {
      "index": 6,
      "slo_id": "S6",
      "level": "apply",
      "question": "What is the improper fraction $\\frac{7}{4}$ written as a Mixed Number?",
      "options": [
        "$1\\frac{3}{4}$",
        "$1\\frac{1}{4}$",
        "$7\\frac{1}{4}$"
      ],
      "correct_index": 0,
      "explanation": "To convert an improper fraction to a mixed number, divide the numerator by the denominator. The quotient is the whole number, the remainder is the new numerator, and the denominator stays the same.",
      "selected_because": "converting seven over four to a mixed number",
      "distractor_misconceptions": {
        "1": "confuses the remainder with the numerator or miscalculates",
        "2": "uses the numerator as the whole number part"
      },
      "option_feedback": {
        "correct": "Excellent! $\\frac{7}{4}$ means 7 divided by 4, which is 1 whole with a remainder of 3, so it's $1\\frac{3}{4}$.",
        "wrong": {
          "1": "When converting $\\frac{7}{4}$, we divide 7 by 4. This gives 1 whole, and there are 3 parts left over, so the fraction part is $\\frac{3}{4}$.",
          "2": "Remember, the numerator 7 is the total number of parts, and the denominator 4 tells us how many parts make a whole. So, 7 parts is 1 whole and 3 parts remaining, making $1\\frac{3}{4}$."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "An improper fraction like seven over four can be written as one whole and three over four. We call this a mixed number.",
      "teaching_error": null
    },
    {
      "index": 7,
      "slo_id": "S6",
      "level": "apply",
      "question": "Convert the improper fraction $\\frac{9}{5}$ into a Mixed Number.",
      "options": [
        "$1\\frac{4}{5}$",
        "$1\\frac{1}{5}$",
        "$2\\frac{4}{5}$"
      ],
      "correct_index": 0,
      "explanation": "To convert an improper fraction to a mixed number, divide the numerator by the denominator. The quotient is the whole number, the remainder is the new numerator, and the denominator stays the same.",
      "selected_because": "converting nine over five to a mixed number",
      "distractor_misconceptions": {
        "1": "miscalculates the remainder",
        "2": "miscalculates the whole number part"
      },
      "option_feedback": {
        "correct": "You got it! $\\frac{9}{5}$ means 9 divided by 5, which is 1 whole with a remainder of 4, so it's $1\\frac{4}{5}$.",
        "wrong": {
          "1": "When you divide 9 by 5, you get 1 whole, and there are 4 parts left over, not 1. So the fraction part should be $\\frac{4}{5}$.",
          "2": "Remember, 9 divided by 5 gives you 1 whole, not 2 wholes. The remainder is 4, so the correct mixed number is $1\\frac{4}{5}$."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Fractions like seven over four, nine over five as improper fractions.",
      "teaching_error": null
    }
  ]
}
